// Rust 变量与可变性完整示例
// 保存为 main.rs 后执行：rustc main.rs && ./main

// 常量：编译期求值，全局可见，必须标注类型
const MAX_RETRY: u32 = 3;
const APP_NAME: &str = "daily-rust";

fn main() {
    // 1. 默认不可变
    let x = 5;
    // x = 6; // ❌ 取消注释会编译失败：cannot assign twice to immutable variable
    println!("x = {}", x);

    // 2. 显式声明可变
    let mut count = 0;
    count += 1;
    count += 1;
    println!("count = {}", count);

    // 3. 变量遮蔽：创建同名新变量，可以改变类型
    let x = x + 1; // x 重新绑定为 6
    let x = x * 2; // x 重新绑定为 12
    println!("shadowed x = {}", x);

    let input = "  42  ";
    let input = input.trim();        // &str -> &str（去空格）
    let input: u32 = input.parse().expect("解析失败"); // &str -> u32
    println!("parsed input = {}", input);

    // 4. 类型标注与不可变的类型固定
    let age: u8 = 25;
    println!("{}: age = {}, max retry = {}", APP_NAME, age, MAX_RETRY);

    // 5. 用下划线前缀显式忽略未使用变量，消除编译器警告
    let _unused = 100;

    // 6. 块作用域中的遮蔽只在该块内生效
    let outer = "before";
    {
        let outer = "inside";
        println!("inner scope: {}", outer);
    }
    println!("outer scope: {}", outer);
}

